import jax; import jax.numpy as jnp; import flax.linen as nn; from typing import Tuple, Optional
# --- SELF-CONTAINED SUBMISSION ---

# --- 1. CKA Helper Functions ---
def _gram_linear(x):
    return x @ x.T
def _center_gram(K):
    n = K.shape[0]
    if n <= 1: return K
    mean_row = jnp.mean(K, axis=1, keepdims=True)
    mean_all = jnp.mean(K)
    return K - mean_row - mean_row.T + mean_all
def _cka(K_c, L_c):
    hsic = jnp.sum(K_c * L_c)
    var_k = jnp.sqrt(jnp.sum(K_c * K_c))
    var_l = jnp.sqrt(jnp.sum(L_c * L_c))
    return hsic / (var_k * var_l)
def cka_from_features(x, y):
    K = _gram_linear(x); L = _gram_linear(y)
    K_c = _center_gram(K); L_c = _center_gram(L)
    return _cka(K_c, L_c)

# --- 2. Network Definitions ---
class ConvLSTMCell(nn.Module):
    features: int
    @nn.compact
    def __call__(self, carry, x): h,c=carry; gates=nn.Conv(4*self.features,(3,3),padding='SAME')(jnp.concatenate([x,h],axis=-1)); i,f,g,o=jnp.split(gates,4,axis=-1); i,f,o=nn.sigmoid(i),nn.sigmoid(f),nn.sigmoid(o); g=jnp.tanh(g); c=f*c+i*g; h=o*jnp.tanh(c); return (h,c),h
class ConvLSTMCellLN(nn.Module):
    features: int
    @nn.compact
    def __call__(self, carry, x): h,c=carry; gates=nn.Conv(4*self.features,(3,3),padding='SAME')(jnp.concatenate([x,h],axis=-1)); gates=nn.LayerNorm(epsilon=1e-5)(gates); i,f,g,o=jnp.split(gates,4,axis=-1); i,f,o=nn.sigmoid(i),nn.sigmoid(f),nn.sigmoid(o); g=jnp.tanh(g); c=f*c+i*g; h=o*jnp.tanh(c); return (h,c),h
class BottleneckBlock(nn.Module):
    features: int
    @nn.compact
    def __call__(self, x): y=nn.Conv(self.features//4,(1,1))(x); y=nn.relu(y); y=nn.Conv(self.features//4,(3,3),padding='SAME')(y); y=nn.relu(y); y=nn.Conv(self.features,(1,1))(y); return nn.relu(x+y)

class KronoNetV4_Probe(nn.Module):
    cnn_features_1:int; cnn_features_2:int; conv_lstm_features:int; dilation_rate:int; steps:int=2; use_input_ln:bool=False; use_gate_ln:bool=False
    @nn.compact
    def __call__(self, x):
        B,H,W,_=x.shape; cnn_out=nn.Conv(self.cnn_features_1,(3,3),padding='SAME',kernel_dilation=self.dilation_rate)(x); cnn_out=nn.relu(cnn_out); cnn_out=BottleneckBlock(self.cnn_features_1)(cnn_out); cnn_out=nn.Conv(self.cnn_features_2,(3,3),padding='SAME',kernel_dilation=self.dilation_rate)(cnn_out); cnn_out=nn.relu(cnn_out); cnn_out=BottleneckBlock(self.cnn_features_2)(cnn_out)
        if self.use_input_ln: cnn_out = nn.LayerNorm()(cnn_out)
        rnn_state = (jnp.zeros((B,H,W,self.conv_lstm_features)), jnp.zeros((B,H,W,self.conv_lstm_features)))
        if self.use_gate_ln: lstm_cell=ConvLSTMCellLN(self.conv_lstm_features)
        else: lstm_cell=ConvLSTMCell(self.conv_lstm_features)
        h,c=rnn_state
        for _ in range(self.steps): (h,c), h_out = lstm_cell((h,c),cnn_out)
        return h_out

# --- 3. The `test()` Function ---
def test():
    key = jax.random.PRNGKey(1337)
    batch_size = 128
    dummy_obs = jax.random.normal(key, (batch_size, 8, 8, 8))
    hparams = {'cnn_features_1':32, 'cnn_features_2':64, 'conv_lstm_features':96, 'dilation_rate':6, 'steps':2}
    configs = {"No LN":{'use_input_ln':False,'use_gate_ln':False},"Internal LN":{'use_input_ln':False,'use_gate_ln':True},"External LN":{'use_input_ln':True,'use_gate_ln':False},"Both LNs":{'use_input_ln':True,'use_gate_ln':True}}
    features = {}
    for name, config_flags in configs.items():
        net = KronoNetV4_Probe(**hparams, **config_flags)
        params = net.init(key, dummy_obs)['params']
        feat_maps = net.apply({'params': params}, dummy_obs)
        features[name] = feat_maps.reshape(batch_size, -1)
    print("--- Representational Similarity (CKA) at Initialization ---")
    config_names = list(configs.keys())
    cka_matrix = jnp.zeros((4, 4))
    for i in range(4):
        for j in range(4):
            cka_val = cka_from_features(features[config_names[i]], features[config_names[j]])
            cka_matrix = cka_matrix.at[i, j].set(cka_val)
    header = "           | " + " | ".join([f"{name:<11}" for name in config_names])
    print(header)
    print("-" * len(header))
    for i, name in enumerate(config_names):
        row = f"{name:<11}| " + " | ".join([f"{cka_matrix[i, j]:<11.4f}" for j in range(4)])
        print(row)
    return "RSA probe complete."
